// 別の環境で再生成しただけで「サマリが正本と食い違っています」と報告される。
const verdictBreakdownRef = "review-triage プラグインの skills/review-triage/references/judgment-flow.md"

// renderVerdictBreakdown は「判定の内訳」の 1 行を組み立てる。出すのはノード ID と
// 件数だけで、各ノードが何を意味するかは書かない — 意味の正本は judgment-flow.md の
// 決定表で、ここに写しを置くと正本を書き換えたときに追随せず、ずれても誰も検出しない
// (この形にした経緯は issue #43 のトリアージ記録)。
func renderVerdictBreakdown(doc *recordDoc) string {
	counts := map[string]int{}
	var order []string
	for _, run := range doc.Runs {
		for _, fd := range run.Findings {
			m := verdictNodeRe.FindStringSubmatch(fd.VerdictReason)
			if m == nil {
				continue
			}
			id := m[2]
			if counts[id] == 0 {
				order = append(order, id)
			}
			counts[id]++
		}
	}
	if len(order) == 0 {
		return ""
	}
	sort.Strings(order)
	parts := make([]string, 0, len(order))
	for _, id := range order {
		parts = append(parts, fmt.Sprintf("**%s** %d 件", id, counts[id]))
	}
	line := "判定の内訳: " + strings.Join(parts, " / ") + "。"
	line += "各ノードの意味は " + verdictBreakdownRef + " の決定表を参照。"
	return line + "\n\n"
}

