            nodes[mm.group(2)]=int(mm.group(3))
    agg={'採択':0,'保留':0,'却下':0}
    for k,v in nodes.items(): agg[kind[k[0]]]+=v
    rows=[l for l in txt.splitlines() if re.match(r'^\| \d+ \| 20',l)]
