        c=[x.strip() for x in l.strip().strip('|').split('|')]
        a+=int(c[6]); h+=int(c[7]); r+=int(c[8])
    ok = (agg['採択'],agg['保留'],agg['却下'])==(a,h,r)
    print(f"{f.split('/')[-1]:52} 内訳={agg} 推移={{'採択':{a},'保留':{h},'却下':{r}}} {'OK' if ok else '<<< MISMATCH'}")
