// judgmentFlowTerminalNodes は決定表から決着ノード (採択 A・保留 H・却下 R) の
// ID 集合を読む。記録の verdict_node がこの集合に含まれるかの照合に使う —
// 形 (正規表現) だけを見ると、判定フローに無いノード ID が素通りし、生成サマリが
// 実在しない ID を案内することになる (回 3 の指摘 4)。
//
// 読めないとき (スキル未導入で正本が不在など) は nil を返す。呼び出し側は
// nil を「照合しない」と読む — 在り処が分からないことを理由に記録の検査を
// 落とすと、スキルを入れずに記録だけ検査する使い方ができなくなる。
// 判定 (D) と評価 (E) のノードは含めない。verdict_node は決着だけを受ける。
func judgmentFlowTerminalNodes(readFile func(string) ([]byte, error)) map[string]bool {
	data, err := readFile(judgmentFlowPath)
	if err != nil {
		return nil
	}
	nodes := map[string]bool{}
	for _, line := range strings.Split(string(data), "\n") {
		m := judgmentFlowTableRowRe.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		// 決着ノードだけを採る。ID の 3 文字目が種別 (JNA1 の A)。
		if id := m[1]; len(id) > 2 && strings.ContainsRune("AHR", rune(id[2])) {
			nodes[id] = true
		}
	}
	if len(nodes) == 0 {
		return nil
	}

